  function renderNests(){if(displayedRaidLayer){map.removeLayer(displayedRaidLayer);displayedRaidLayer=null}poiLayer.clearLayers();nestBoundaryLayer.clearLayers();const query=$("#search").value.trim().toLocaleLowerCase("en"),bounds=map.getBounds().pad(.2);for(const group of groupedNests()){if(!bounds.contains([group.latitude,group.longitude])||!withinGeofence(group.latitude,group.longitude)||query&&!`${group.placeName} ${group.candidates.map(candidate=>candidate.pokemonName).join(" ")}`.toLocaleLowerCase("en").includes(query))continue;const top=group.candidates[0],tooltip=top?`<strong>${escape(group.placeName||"Reported nest")}</strong><span>${escape(top.pokemonName)}<small>${top.confirmationCount} confirmation${top.confirmationCount===1?"":"s"}</small></span>`:`<strong>${escape(group.placeName||"Potential nest area")}</strong><span>Potential nest area<small>OpenStreetMap · Tap to report</small></span>`;if(map.getZoom()>=14)for(const line of group.boundary||[])if(Array.isArray(line)&&line.length>=3)L.polygon(line,{renderer:nestBoundaryRenderer,color:top?"#25b975":"#6f9588",weight:top?3:2,opacity:top?.9:.55,dashArray:top?null:"5 5",fillColor:"#25b975",fillOpacity:top?.16:.08,interactive:true}).bindTooltip(tooltip,{className:"research-hover",direction:"top",sticky:true}).on("click",()=>renderNestSheet(group)).addTo(nestBoundaryLayer);L.marker([group.latitude,group.longitude],{icon:nestIcon(group)}).bindTooltip(tooltip,{className:"research-hover",direction:"top",offset:[0,-27]}).on("click",()=>renderNestSheet(group)).addTo(poiLayer)}updateNestProgress()}
  function renderNestSheet(group){const hasReports=group.candidates.length>0,rows=group.candidates.map(candidate=>`<div class="nest-candidate"><img src="${escape(pokemonSpriteUrl(candidate.pokemonId))}" data-fallback="${escape(pokemonAddressableSpriteUrl(candidate.pokemonId))}" data-fallback-secondary="${escape(pokemonFallbackSpriteUrl(candidate.pokemonId))}" alt="" loading="lazy" decoding="async"><span><strong>${escape(candidate.pokemonName)}</strong><small>${candidate.confirmationCount} confirmation${candidate.confirmationCount===1?"":"s"}</small></span><button type="button" data-nest-confirm="${escape(candidate.pokemonId)}"${candidate.confirmedByYou?" disabled":""}>${candidate.confirmedByYou?"Confirmed":"Confirm"}</button></div>`).join("");$("#sheetContent").innerHTML=`<span class="badge">${hasReports?"Nest":"Potential nest"}</span><h2>${escape(group.placeName||"Potential nest area")}</h2>${hasReports?`<p class="nest-reset-note">${escape(nestResetText())}</p>`:'<p class="nest-reset-note">No Pokémon reported for this migration yet.</p>'}<div class="nest-list">${rows}</div><div class="sheet-actions">${directionsAction(group)}<button id="changeNestSpecies" class="primary">Report species</button></div>`;showSheet();$$('[data-nest-confirm]').forEach(button=>button.addEventListener("click",()=>confirmNestCandidate(group,group.candidates.find(candidate=>candidate.pokemonId===button.dataset.nestConfirm),button)));$("#changeNestSpecies").addEventListener("click",()=>openNestReportAt(group,group))}
  async function loadNestSpecies(){if(state.nestSpecies.length)return state.nestSpecies;const data=await loadPokemonCpData(),unique=new Map();for(const pokemon of data){const id=String(pokemon.pokemon_id||""),name=String(pokemon.pokemon_name||"").trim(),form=String(pokemon.form||"normal").toLocaleLowerCase("en");if(id&&name&&(form==="normal"||!unique.has(name.toLocaleLowerCase("en"))))unique.set(name.toLocaleLowerCase("en"),{id,name})}state.nestSpecies=[...unique.values()].sort((a,b)=>a.name.localeCompare(b.name));return state.nestSpecies}
