    $$('#questFilterOptions [data-quest-keys]').forEach(box=>{box.indeterminate=box.dataset.partial==="true";box.addEventListener("change",applyQuestFilters)});$$('#questFilterOptions [data-reward-key]').forEach(parent=>{parent.addEventListener("click",event=>event.stopPropagation());parent.addEventListener("change",()=>{parent.closest('.reward-filter-group').querySelectorAll('[data-quest-keys]').forEach(box=>{box.checked=parent.checked;box.indeterminate=false});applyQuestFilters()})});$("#showUnreported").onchange=applyQuestFilters;syncRewardGroups();filterQuestOptions();updateQuestFilterButton();updateQuestBulkButton()
