  async function loadScrapedDuckCatalogue(){const cacheKey="pokemap-research-catalogue-v2";try{const response=await fetch(CONFIG.scrapedDuckResearchUrl,{cache:"no-store",credentials:"omit"});if(!response.ok)throw new Error(`ScrapedDuck returned HTTP ${response.status}`);const rows=await response.json();if(!Array.isArray(rows))throw new Error("unexpected ScrapedDuck response");const tasks=rows.map((row,index)=>{const raw=String(row.text||"").trim(),seen=new Set();const rewards=(Array.isArray(row.rewards)?row.rewards:[]).map(reward=>{const label=String(reward.name||reward.label||"").trim(),id=slug(label),image=String(reward.image||"").trim();if(!label||!id||seen.has(id))return null;seen.add(id);return{id,label,type:"ENCOUNTER",...(image.startsWith("https://cdn.leekduck.com/")?{image}:{})}}).filter(Boolean);return raw&&rewards.length?{id:`${slug(raw)}-${index}`,text:plainText(raw),category:"research",rewards}:null}).filter(task=>task&&!isArResearchTask(task));if(!tasks.length)throw new Error("ScrapedDuck returned no tasks");localStorage.setItem(cacheKey,JSON.stringify({savedAt:Date.now(),tasks}));return tasks}catch(error){try{const cached=JSON.parse(localStorage.getItem(cacheKey));if(cached?.tasks?.length)return cached.tasks.filter(task=>!isArResearchTask(task))}catch{}throw error}}
  async function submitResearch(taskId,rewardId){if(CONFIG.turnstileSiteKey&&turnstileWidget===undefined){toast("Human verification is still loading");return}const controls=$$("#reportDialog button"),reportedStop=state.selected;controls.forEach(button=>button.disabled=true);try{const turnstileToken=turnstileWidget===undefined?null:turnstile.getResponse(turnstileWidget);await reportApi("/api/research/report",{method:"POST",body:JSON.stringify({pokestopId:reportedStop.id,taskId,rewardId,latitude:reportedStop.latitude,longitude:reportedStop.longitude,reporterId:REPORTER_ID,turnstileToken})});$("#reportDialog").close();closeSheet();playReportFireworks(Number(reportedStop.latitude),Number(reportedStop.longitude));state.selected=null;state.selectedReports=[];toast("Thank you for the report!");announceReportUpdate();await loadStatic()}catch(err){toast(err.message);if(turnstileWidget!==undefined)turnstile.reset(turnstileWidget)}finally{controls.forEach(button=>button.disabled=false)}}
