  function registerInstallButton(){const button=$("#installApp"),standalone=window.matchMedia?.("(display-mode: standalone)").matches||navigator.standalone===true,isIos=/iPad|iPhone|iPod/.test(navigator.userAgent)||navigator.platform==="MacIntel"&&navigator.maxTouchPoints>1;if(standalone)return;let installPrompt=null;if(isIos)button.classList.remove("hidden");window.addEventListener("beforeinstallprompt",event=>{event.preventDefault();installPrompt=event;button.classList.remove("hidden")});window.addEventListener("appinstalled",()=>{installPrompt=null;button.classList.add("hidden");toast("PoGo Boekenberg installed!")});button.addEventListener("click",async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;button.classList.add("hidden");return}if(isIos)toast("In Safari, tap Share, then Add to Home Screen")})}
  function playReportFireworks(latitude,longitude){if(!Number.isFinite(Number(latitude))||!Number.isFinite(Number(longitude))||window.matchMedia?.("(prefers-reduced-motion: reduce)").matches)return;const point=map.latLngToContainerPoint([latitude,longitude]),burst=document.createElement("div"),colors=["#52e0a4","#54b9ff","#ffbd59","#ff6b71","#c06cff"];burst.className="report-firework";burst.style.left=`${point.x}px`;burst.style.top=`${point.y}px`;for(let wave=0;wave<3;wave++)for(let i=0;i<16;i++){const particle=document.createElement("i"),angle=Math.PI*2*(i/16)+wave*.17,distance=58+wave*30+(i%3)*9;particle.style.setProperty("--firework-x",`${Math.cos(angle)*distance}px`);particle.style.setProperty("--firework-y",`${Math.sin(angle)*distance}px`);particle.style.setProperty("--firework-delay",`${wave*.14}s`);particle.style.setProperty("--firework-color",colors[(i+wave*2)%colors.length]);burst.appendChild(particle)}map.getContainer().appendChild(burst);setTimeout(()=>burst.remove(),1800)}
  let userLocationMarker,userAccuracyCircle;function showUserLocation(event){const accuracy=Math.max(0,Number(event.accuracy)||0);if(!userAccuracyCircle)userAccuracyCircle=L.circle(event.latlng,{radius:accuracy,color:"#54b9ff",weight:1.5,opacity:.8,fillColor:"#54b9ff",fillOpacity:.13,interactive:false}).addTo(locationLayer);else userAccuracyCircle.setLatLng(event.latlng).setRadius(accuracy);if(!userLocationMarker)userLocationMarker=L.circleMarker(event.latlng,{radius:7,color:"#fff",weight:3,fillColor:"#168ee3",fillOpacity:1}).bindTooltip("You are here").addTo(locationLayer);else userLocationMarker.setLatLng(event.latlng);userLocationMarker.bringToFront()}
  let adminLocationMarker,adminAccuracyCircle;async function loadAdminLocation(){try{const location=await reportApi("/api/location");if(!location.active){sharedLocationLayer.clearLayers();adminLocationMarker=adminAccuracyCircle=null;return}const latitude=Number(location.latitude),longitude=Number(location.longitude),accuracy=Math.max(0,Number(location.accuracy)||0);if(!Number.isFinite(latitude)||!Number.isFinite(longitude))return;const latlng=L.latLng(latitude,longitude);if(!adminAccuracyCircle)adminAccuracyCircle=L.circle(latlng,{radius:accuracy,color:"#a855f7",weight:1.5,opacity:.85,fillColor:"#a855f7",fillOpacity:.12,interactive:false}).addTo(sharedLocationLayer);else adminAccuracyCircle.setLatLng(latlng).setRadius(accuracy);if(!adminLocationMarker)adminLocationMarker=L.marker(latlng,{icon:L.divIcon({className:"admin-location-marker",html:'<span aria-hidden="true"><b>&#9733;</b></span>',iconSize:[34,34],iconAnchor:[17,17]})}).bindTooltip("Community Ambassador · live",{direction:"top",offset:[0,-17]}).addTo(sharedLocationLayer);else adminLocationMarker.setLatLng(latlng);adminLocationMarker.bringToFront()}catch{}}
