  function selectMode(mode,button){const content={research:{title:"Find today’s research",copy:"Tap a PokéStop to view or report its current Field Research.",footer:"Live POIs and community reports",search:"Search places or rewards"},raids:{title:"Find nearby raids",copy:"",footer:"Live raids in view",search:"Search bosses or tiers"},nests:{title:"Find nearby nests",copy:"Community reports automatically reset with each nest migration.",footer:"Current migration reports",search:"Search places or Pokémon"},planner:{title:"Inspect S2 cells",copy:"Use S2 overlays and optional Power Spot exclusion zones to evaluate Wayspot locations.",footer:"Live Wayspots",search:"Search places"}}[mode];if(!content)return;visibleController?.abort();setNestPlacement(false);$$(".modes button").forEach(item=>item.classList.toggle("active",item===button));state.mode=mode;syncAdminLocationVisibility();try{localStorage.setItem("pokemap-mode-v1",mode)}catch{}document.body.classList.toggle("planner",mode==="planner");document.body.classList.toggle("raids",mode==="raids");document.body.classList.toggle("nests",mode==="nests");$("#modeTitle").textContent=content.title;$("#modeCopy").textContent=content.copy;$("#modeCopy").classList.toggle("hidden",!content.copy);$("#footerCopy").textContent=content.footer;$("#search").placeholder=content.search;$("#search").value="";closeMobileSettings();closeMobileSearch();closeSheet();$$("dialog[open]").forEach(dialog=>dialog.close());loadCells();if(mode==="research"){renderPois();loadSharedReportData();loadVisible();return}if(mode==="raids"){loadVisible();return}if(mode==="nests"){renderPois();loadNestReports();loadVisible();return}if(map.getZoom()<15)map.setZoom(15);else loadVisible()}
